+        'png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'ico',
+        'woff', 'woff2', 'ttf', 'eot',
+        'yml', 'yaml', 'xml', 'xliff', 'po', 'mo',
+        'sql', 'lock',
+    ];
